import { Skeleton } from "@/components/ui/skeleton"

export default function Loading() {
    return (
        <div className="flex flex-1 flex-col gap-4 p-4 pt-0">
            <div className="flex items-center justify-between space-y-2">
                <Skeleton className="h-8 w-[100px]" />
                <Skeleton className="h-10 w-[80px]" />
            </div>
            <div className="flex items-center space-x-2">
                <Skeleton className="h-10 flex-1" />
            </div>
            <div className="rounded-md border">
                <div className="w-full overflow-auto">
                    <table className="w-full caption-bottom text-sm">
                        <thead className="[&_tr]:border-b">
                            <tr className="border-b">
                                <th className="h-12 px-4"><Skeleton className="h-4 w-[100px]" /></th>
                                <th className="h-12 px-4"><Skeleton className="h-4 w-[60px]" /></th>
                                <th className="h-12 px-4"><Skeleton className="h-4 w-[80px]" /></th>
                                <th className="h-12 px-4"><Skeleton className="h-4 w-[80px]" /></th>
                            </tr>
                        </thead>
                        <tbody>
                            {Array.from({ length: 5 }).map((_, i) => (
                                <tr key={i} className="border-b">
                                    <td className="p-4"><Skeleton className="h-4 w-[150px]" /></td>
                                    <td className="p-4"><Skeleton className="h-4 w-[40px]" /></td>
                                    <td className="p-4"><Skeleton className="h-4 w-[100px]" /></td>
                                    <td className="p-4"><Skeleton className="h-4 w-[100px]" /></td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    )
}
